const filters = { query: '', status: '', owner: '' };
const companyNames = { 'tenant-A': 'Empresa Andina', 'tenant-B': 'Empresa Caribe' };
let kanbanProjectId = '';
let ganttProjectId = '';
let ganttScale = 'month';
let ganttAnchor = new Date();
let costProjectId = '';
const reportFilters = { projectId: '', assignee: '', priority: '', status: '' };
const readNotifications = new Set();
let selectedProjectId = null;
let activeProjectView = null;

const escapeHtml = (value) => String(value).replace(/[&<>'"]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[character]));
const formatTime = (date) => new Intl.DateTimeFormat('es-VE', { hour: '2-digit', minute: '2-digit' }).format(new Date(date));
let noticeTimer;
function showError(result) {
  if (result?.ok !== false) return;
  let notice = document.querySelector('#operationNotice');
  if (!notice) { notice = document.createElement('aside'); notice.id = 'operationNotice'; notice.setAttribute('role', 'alert'); notice.style.cssText = 'position:fixed;right:24px;bottom:24px;z-index:20;max-width:390px;padding:14px 16px;border:1px solid #e3b2b2;border-radius:9px;background:#fff5f5;color:#7d1d1d;box-shadow:0 12px 32px #001b3926'; document.body.append(notice); }
  notice.innerHTML = `<strong>${escapeHtml(result.error.code)}</strong><p>${escapeHtml(result.error.message ?? 'No se pudo completar la operación.')}</p><button type="button" aria-label="Cerrar aviso">×</button>`;
  notice.querySelector('button').addEventListener('click', () => notice.remove());
  clearTimeout(noticeTimer); noticeTimer = setTimeout(() => notice.remove(), 7000);
}
const client = new Proxy(rawClient, { get(target, property) { const value = target[property]; if (typeof value !== 'function') return value; return (...args) => { const result = value(...args); showError(result); return result; }; } });

function filteredProjects() {
  return client.listProjects().filter((project) => {
    const text = `${project.name} ${project.owner}`.toLowerCase();
    return (!filters.query || text.includes(filters.query)) && (!filters.status || project.status === filters.status) && (!filters.owner || project.owner === filters.owner);
  });
}

function refreshOwnerFilter(projects) {
  const current = $('#ownerFilter').value;
  const owners = [...new Set(projects.map((project) => project.owner))].sort();
  $('#ownerFilter').innerHTML = `<option value="">Todos</option>${owners.map((owner) => `<option value="${escapeHtml(owner)}">${escapeHtml(owner)}</option>`).join('')}`;
  $('#ownerFilter').value = owners.includes(current) ? current : '';
}

function render() {
  const session = client.getSession(); const user = session.user; if (user) { $('.avatar').textContent = user.displayName.split(' ').map((part) => part[0]).join('').slice(0, 2); $('.user-label').innerHTML = `${escapeHtml(user.displayName)}<small>${escapeHtml(user.role)}</small>`; $('#tenantSelect').innerHTML = user.allowedTenantIds.map((tenant) => `<option value="${tenant}">${escapeHtml(companyNames[tenant] ?? tenant)}</option>`).join(''); $('#tenantSelect').value = session.tenantId; }
  const allProjects = client.listProjects();
  refreshOwnerFilter(allProjects);
  const projects = filteredProjects();
  const tenant = client.getTenant();
  const company = companyNames[tenant] ?? tenant;
  const audit = client.getAudit();
  $('#activeProjects').textContent = allProjects.filter((project) => project.status === 'En curso').length;
  $('#planningProjects').textContent = allProjects.filter((project) => project.status === 'Planificación').length;
  $('#openTasks').textContent = allProjects.reduce((total, project) => total + project.tasks.filter((task) => !task.archivedAt).length, 0);
  $('#auditCount').textContent = audit.length;
  $('#tenantChip').textContent = company;
  $('#tenantReadout').value = company;
  $('#projectListCaption').textContent = `Proyectos disponibles para ${company}`;
  const activeFilters = [filters.query, filters.status, filters.owner].filter(Boolean).length;
  $('#filterCount').textContent = `${activeFilters} filtro${activeFilters === 1 ? '' : 's'} activo${activeFilters === 1 ? '' : 's'}`;
  projectList.innerHTML = projects.map((project) => `<tr class="${selectedProjectId === project.id ? 'project-selected' : ''}" data-project-id="${project.id}">
    <td><span class="project-name">${escapeHtml(project.name)}</span><span class="project-code">${project.id}</span></td>
    <td>${escapeHtml(project.owner)}</td>
    <td><span class="status ${project.status === 'Planificación' ? 'planning' : ''}">${escapeHtml(project.status)}</span></td>
    <td>${project.tasks.filter((task) => !task.archivedAt).length}</td>
    <td>${escapeHtml(company)}</td><td><button class="open-board table-action ${selectedProjectId === project.id && activeProjectView === 'board' ? 'action-active' : ''}" data-project-id="${project.id}" type="button" aria-pressed="${selectedProjectId === project.id && activeProjectView === 'board'}">Abrir tablero</button><button class="open-gantt table-action ${selectedProjectId === project.id && activeProjectView === 'gantt' ? 'action-active' : ''}" data-project-id="${project.id}" type="button" aria-pressed="${selectedProjectId === project.id && activeProjectView === 'gantt'}">Abrir Gantt</button><button class="view-detail table-action ${selectedProjectId === project.id && activeProjectView === 'info' ? 'action-active' : ''}" data-project-id="${project.id}" type="button" aria-pressed="${selectedProjectId === project.id && activeProjectView === 'info'}">Información del proyecto</button></td>
  </tr>`).join('');
  $('#emptyState').classList.toggle('hidden', projects.length > 0);
  auditList.innerHTML = audit.length ? audit.map((entry) => `<li>${escapeHtml(entry.type)}: ${escapeHtml(entry.payload.name ?? entry.payload.code ?? entry.payload.permission ?? entry.payload.reason ?? '')}<time>${formatTime(entry.occurredAt)}</time></li>`).join('') : '<li>Sin eventos en esta sesión.</li>';
  renderNotifications(audit);
  if (!$('#kanbanView').classList.contains('hidden')) renderKanban();
  if (!$('#ganttView').classList.contains('hidden')) renderGantt();
  if (!$('#costView').classList.contains('hidden')) renderCosts();
  if (!$('#reportView').classList.contains('hidden')) renderReports();
}
function showLogin() { const users = client.listSessionUsers(); if (users.length) { $('#loginUserSelect').innerHTML = users.map((user) => `<option value="${user.userId}">${escapeHtml(user.displayName)} · ${escapeHtml(user.role)}</option>`).join(''); $('#loginUserSelect').value = users.some((user) => user.userId === 'user-admin') ? 'user-admin' : users[0].userId; } $('#loginView').classList.remove('hidden'); document.querySelector('.app-shell').classList.add('hidden'); }
function resumeSession() { $('#loginView').classList.add('hidden'); document.querySelector('.app-shell').classList.remove('hidden'); showProjects(); }

function renderNotifications(audit = client.getAudit()) {
  const relevant = audit.filter((entry) => ['CommentAdded', 'CardMoved', 'TaskStatusChanged', 'TimeEntryAdded', 'CostEntryAdded'].includes(entry.type)).slice(0, 12); const unread = relevant.filter((entry) => !readNotifications.has(entry.requestId)).length; $('#notificationCount').textContent = unread; $('#notificationCount').classList.toggle('hidden', unread === 0); notificationPanel.innerHTML = `<div class="notification-header"><h3>Notificaciones</h3><button id="readAllNotifications" class="table-action" type="button">Marcar leídas</button></div>${relevant.length ? relevant.map((entry) => `<button class="notification-item ${readNotifications.has(entry.requestId) ? '' : 'unread'}" data-request-id="${entry.requestId}" data-project-id="${entry.payload.projectId ?? ''}" data-task-id="${entry.payload.taskId ?? ''}" type="button"><strong>${escapeHtml(entry.type === 'CommentAdded' ? 'Nuevo comentario' : entry.type === 'CardMoved' || entry.type === 'TaskStatusChanged' ? 'Tarjeta actualizada' : entry.type === 'TimeEntryAdded' ? 'Tiempo registrado' : 'Costo registrado')}</strong><span>${escapeHtml(entry.payload.name ?? entry.payload.taskId ?? 'Actividad en proyecto')}</span><small>${formatTime(entry.occurredAt)}</small></button>`).join('') : '<p>Sin notificaciones nuevas.</p>'}`;
}

const listColor = (color) => ({ verde: '#8fc7a8', 'ámbar': '#e8bf75', gris: '#b8c4cc', azul: '#9cc9dc' }[color] ?? '#9cc9dc');
const taskList = (project, task) => project.boardLists?.find((list) => list.id === task.listId);
const taskIsDone = (project, task) => Boolean(taskList(project, task)?.isDone || task.status === 'Completada');
function renderKanban() {
  const projects = client.listProjects();
  if (!projects.length) { $('#kanbanProjectSelect').innerHTML = ''; $('#kanbanProjectHeader').innerHTML = ''; $('#kanbanSummary').innerHTML = ''; $('#kanbanBoard').innerHTML = '<p class="kanban-empty">No hay proyectos en la empresa seleccionada.</p>'; return; }
  if (!projects.some((project) => project.id === kanbanProjectId)) kanbanProjectId = projects[0].id;
  $('#kanbanProjectSelect').innerHTML = projects.map((project) => `<option value="${project.id}" ${project.id === kanbanProjectId ? 'selected' : ''}>${escapeHtml(project.name)} · ${escapeHtml(project.status)}</option>`).join('');
  const project = projects.find((item) => item.id === kanbanProjectId); const lists = project.boardLists.filter((list) => !list.archivedAt).sort((a, b) => a.position - b.position); const counts = Object.fromEntries(lists.map((list) => [list.id, project.tasks.filter((task) => !task.archivedAt && task.listId === list.id).length]));
  const completedThisSession = client.getAudit().filter((entry) => entry.type === 'TaskStatusChanged' && entry.payload.newStatus === 'Completada').length;
  const total = project.tasks.filter((task) => !task.archivedAt).length; const completed = project.tasks.filter((task) => !task.archivedAt && lists.find((list) => list.id === task.listId)?.isDone).length; const progress = total ? Math.round((completed / total) * 100) : 0; const locked = project.status === 'Cerrado';
  $('#kanbanProjectHeader').innerHTML = `<div><h3 tabindex="-1">Tablero: ${escapeHtml(project.name)}</h3><p>Responsable: ${escapeHtml(project.owner)} · Estado: ${escapeHtml(project.status)}</p><p>${completed} de ${total} tarjetas finalizadas · Avance ${progress}%</p></div><div class="header-actions"><button class="secondary-button kanban-detail" type="button">Información del proyecto</button><button class="secondary-button kanban-add-list" type="button" ${locked ? 'disabled' : ''}>+ Añadir lista</button><button class="primary-button kanban-new-task" type="button" ${locked ? 'disabled' : ''}>+ Nueva tarjeta</button></div>`;
  $('#kanbanSummary').innerHTML = `<span>${lists.length} listas activas</span><span>${completed} tarjetas finalizadas</span><span>Completadas en sesión: ${completedThisSession}</span>`;
  $('#kanbanBoard').innerHTML = lists.map((list) => { const tasks = project.tasks.filter((task) => !task.archivedAt && task.listId === list.id); return `<section class="kanban-column" data-list-id="${list.id}" style="border-top:4px solid ${listColor(list.color)}"><h3><span>${escapeHtml(list.name)}${list.wipLimit ? ` · ${counts[list.id]}/${list.wipLimit}` : ''}</span><span>${tasks.length}</span><button class="icon-button list-menu" data-list-id="${list.id}" type="button" aria-label="Opciones de la lista ${escapeHtml(list.name)}" ${locked ? 'disabled' : ''}>⋮</button></h3>${tasks.length ? tasks.map((task) => { const priority = task.priority ?? 'Media'; const checklist = task.checklist ?? []; const checksDone = checklist.filter((item) => item.completed).length; const cost = taskCostSummary(task); const collaboration = `${task.comments?.length ? `💬 ${task.comments.length}` : ''}${task.attachments?.length ? ` · 📎 ${task.attachments.length}` : ''}`; const movable = !list.isDone && !locked; return `<article class="kanban-card" data-task-id="${task.id}" draggable="${movable}" tabindex="0" role="button" aria-label="Ver detalle de tarjeta ${escapeHtml(task.name)}"><div class="card-top"><strong>${task.parentTaskId ? '↳ ' : ''}${escapeHtml(task.name)}</strong><button class="icon-button card-menu" data-task-id="${task.id}" type="button" aria-label="Opciones de tarjeta">⋮</button></div><span class="card-status">${escapeHtml(list.name)}</span><small>${escapeHtml(task.assignee)}</small><span class="priority ${escapeHtml(priority)}">Prioridad ${escapeHtml(priority)}</span>${checklist.length ? `<small>☑ ${checksDone}/${checklist.length}</small>` : ''}${collaboration ? `<small>${collaboration}</small>` : ''}${cost.hours ? `<small>⏱ ${cost.hours} h${cost.hoursOver || cost.budgetOver ? ' · ⚠' : ''}</small>` : ''}${movable ? `<button class="primary-button card-primary-action" data-task-id="${task.id}" type="button">Mover tarjeta</button>` : list.isDone ? '<span class="card-completed">Finalizada</span>' : ''}</article>`; }).join('') : '<p class="kanban-empty">No hay tarjetas en esta lista.</p>'}</section>`; }).join('');
}

function shiftGanttAnchor(direction) { const date = new Date(ganttAnchor); if (ganttScale === 'week') date.setDate(date.getDate() + direction * 7); else if (ganttScale === 'quarter') date.setMonth(date.getMonth() + direction * 3); else date.setMonth(date.getMonth() + direction); ganttAnchor = date; }
function renderGantt() {
  const projects = client.listProjects(); if (!projects.length) return;
  if (!projects.some((project) => project.id === ganttProjectId)) ganttProjectId = projects[0].id;
  $('#ganttProjectSelect').innerHTML = projects.map((project) => `<option value="${project.id}" ${project.id === ganttProjectId ? 'selected' : ''}>${escapeHtml(project.name)} · ${escapeHtml(project.status)}</option>`).join('');
  const project = projects.find((item) => item.id === ganttProjectId); const progress = projectProgress(project); const range = ganttRange(ganttAnchor, ganttScale); const rangeLabel = new Intl.DateTimeFormat('es-VE', { day: '2-digit', month: 'short', year: 'numeric' }); $('#ganttPeriod').textContent = `${rangeLabel.format(new Date(`${range.start}T00:00:00`))} — ${rangeLabel.format(new Date(`${range.end}T00:00:00`))}`;
  $('#ganttProjectHeader').innerHTML = `<div><h3>Gantt: ${escapeHtml(project.name)}</h3><p>Responsable: ${escapeHtml(project.owner)} · Estado: ${escapeHtml(project.status)}</p><p>${progress.done} de ${progress.total} tarjetas finalizadas · Avance ${progress.percent}%</p></div><div class="header-actions"><button class="secondary-button gantt-detail" type="button">Información del proyecto</button></div>`;
  $('#ganttScale').querySelectorAll('button').forEach((button) => button.classList.toggle('active', button.dataset.scale === ganttScale));
  const days = Array.from({ length: range.days }, (_, index) => { const date = new Date(`${range.start}T00:00:00`); date.setDate(date.getDate() + index); return `<span>${date.getDate()}</span>`; }).join('');
  const tasks = project.tasks.filter((task) => !task.archivedAt); const planned = tasks.filter((task) => taskSchedule(task).kind !== 'unscheduled'); const unscheduled = tasks.filter((task) => taskSchedule(task).kind === 'unscheduled');
  const rows = planned.map((task) => { const schedule = taskSchedule(task); const placement = barPlacement(schedule, range); const list = taskList(project, task); const status = list?.name ?? task.status; const label = `${task.name} · ${task.assignee} · ${status}`; let calendar = `<div class="gantt-calendar" style="--days:${range.days}">`; if (schedule.kind === 'invalid') calendar += '<span class="gantt-invalid">Fechas inválidas</span>'; else if (placement && schedule.kind === 'milestone') calendar += `<button class="gantt-milestone" data-task-id="${task.id}" style="left:calc(${placement.left}% - 7px)" aria-label="Abrir tarjeta ${escapeHtml(task.name)}, vence ${schedule.date}"></button>`; else if (placement) calendar += `<button class="gantt-bar ${escapeHtml(task.priority ?? 'Media')} ${taskIsDone(project, task) ? 'done' : ''} ${status.toLowerCase().includes('bloque') ? 'blocked' : ''}" data-task-id="${task.id}" style="left:${placement.left}%;width:${placement.width}%" aria-label="Abrir tarjeta ${escapeHtml(task.name)}">${escapeHtml(task.name)}</button>`; calendar += '</div>'; return `<div class="gantt-label" data-task-id="${task.id}" role="button" tabindex="0" aria-label="Abrir tarjeta ${escapeHtml(task.name)}"><strong>${escapeHtml(task.name)}</strong><small>${escapeHtml(task.assignee)} · ${escapeHtml(status)} · ${escapeHtml(task.priority ?? 'Media')}</small></div>${calendar}`; }).join('');
  const phaseRows = project.phases.length ? `<div class="gantt-phase">Fases: ${project.phases.map((phase) => escapeHtml(phase.name)).join(' · ')}</div>` : ''; const milestones = project.milestones.length ? `<p class="gantt-milestones">Hitos: ${project.milestones.map((milestone) => `${escapeHtml(milestone.name)} (${escapeHtml(milestone.targetDate)})`).join(' · ')}</p>` : '';
  $('#ganttTimeline').innerHTML = `${milestones}<div class="gantt-grid"><div class="gantt-label"><strong>Tarjeta</strong><small>Responsable · Lista · Prioridad</small></div><div class="gantt-calendar gantt-days" style="--days:${range.days}">${days}</div>${phaseRows}${rows || '<div class="gantt-label"><strong>Sin tareas planificadas</strong></div><div class="gantt-calendar"></div>'}</div>`;
  $('#ganttUnscheduled').innerHTML = `<strong>Sin planificación</strong><p>${unscheduled.length ? 'Estas tarjetas no tienen fecha de inicio ni vencimiento.' : 'Todas las tarjetas tienen al menos una fecha.'}</p>${unscheduled.length ? `<ul>${unscheduled.map((task) => `<li><button class="gantt-open-task table-action" data-task-id="${task.id}" type="button">${escapeHtml(task.name)}</button> · ${escapeHtml(task.assignee)}</li>`).join('')}</ul>` : ''}`;
}

function renderCosts() {
  const projects = client.listProjects(); if (!projects.length) return; const currentAssignee = $('#costAssignee').value; const currentTask = $('#costTask').value; if (!projects.some((project) => project.id === costProjectId)) costProjectId = projects[0].id;
  $('#costProjectSelect').innerHTML = projects.map((project) => `<option value="${project.id}" ${project.id === costProjectId ? 'selected' : ''}>${escapeHtml(project.name)}</option>`).join(''); const project = projects.find((item) => item.id === costProjectId); const summary = client.getProjectCostSummary({ projectId: project.id }).data; $('#costSummary').innerHTML = `<span>${summary.hours} h reales</span><span>Tiempo: ${currency} ${summary.timeCost.toFixed(2)}</span><span>Manual: ${currency} ${summary.manualCost.toFixed(2)}</span><span>Total: ${currency} ${summary.total.toFixed(2)}</span><span>Sobreconsumo: ${summary.overrunTasks}</span>`;
  const assignees = [...new Set(project.tasks.flatMap((task) => (task.timeEntries ?? []).map((entry) => entry.assignee)))]; $('#costAssignee').innerHTML = `<option value="">Todos</option>${assignees.map((name) => `<option value="${escapeHtml(name)}">${escapeHtml(name)}</option>`).join('')}`; $('#costAssignee').value = assignees.includes(currentAssignee) ? currentAssignee : ''; $('#costTask').innerHTML = `<option value="">Todas</option>${project.tasks.map((task) => `<option value="${task.id}">${escapeHtml(task.name)}</option>`).join('')}`; $('#costTask').value = project.tasks.some((task) => task.id === currentTask) ? currentTask : '';
  const from = $('#costFrom').value; const to = $('#costTo').value; const assignee = $('#costAssignee').value; const taskFilter = $('#costTask').value; const entries = project.tasks.flatMap((task) => [...(task.timeEntries ?? []).map((entry) => ({ ...entry, task, kind: 'Tiempo' })), ...(task.costEntries ?? []).map((entry) => ({ ...entry, task, kind: entry.type }))]).filter((entry) => (!from || entry.date >= from) && (!to || entry.date <= to) && (!assignee || entry.assignee === assignee) && (!taskFilter || entry.task.id === taskFilter)).sort((a, b) => b.date.localeCompare(a.date)); $('#costEntriesTable').innerHTML = entries.length ? entries.map((entry) => `<tr><td>${escapeHtml(entry.date)}</td><td>${escapeHtml(entry.task.name)}</td><td>${escapeHtml(entry.assignee ?? entry.concept)}</td><td>${escapeHtml(entry.kind)}</td><td>${entry.hours ?? '—'}</td><td>${currency} ${(entry.cost ?? entry.amount).toFixed(2)}</td></tr>`).join('') : '<tr><td colspan="6">Sin registros para los filtros seleccionados.</td></tr>';
}
function renderReports() { const projects = client.listProjects(); $('#reportProject').innerHTML = `<option value="">Todos los proyectos</option>${projects.map((project) => `<option value="${project.id}">${escapeHtml(project.name)}</option>`).join('')}`; $('#reportProject').value = reportFilters.projectId; const assignees = [...new Set(projects.flatMap((project) => project.tasks.map((task) => task.assignee)))]; $('#reportAssignee').innerHTML = `<option value="">Todos</option>${assignees.map((name) => `<option value="${escapeHtml(name)}">${escapeHtml(name)}</option>`).join('')}`; $('#reportAssignee').value = reportFilters.assignee; const rows = reportRows(projects, reportFilters); const summary = reportSummary(projects, rows); $('#reportSummary').innerHTML = `<span>${summary.tasks} tarjetas</span><span>${summary.done} finalizadas · ${summary.progress}%</span><span>${summary.hours} h</span><span>Total: ${currency} ${summary.total.toFixed(2)}</span><span>Riesgos: ${summary.risks.length}</span>`; $('#reportRisks').innerHTML = summary.risks.length ? `<p><strong>Riesgos:</strong> ${summary.risks.map((row) => `${escapeHtml(row.task.name)} — ${escapeHtml(row.risk)}`).join(' · ')}</p>` : '<p>Sin riesgos detectados.</p>'; $('#reportTable').innerHTML = rows.length ? rows.map(({ project, task, list }) => `<tr><td>${escapeHtml(project.name)}</td><td>${escapeHtml(task.name)}</td><td>${escapeHtml(task.assignee)}</td><td>${escapeHtml(list?.name ?? '')}</td><td>${escapeHtml(task.priority ?? '')}</td><td>${escapeHtml(task.dueDate ?? '—')}</td><td>${escapeHtml(summary.risks.find((risk) => risk.task.id === task.id)?.risk ?? '—')}</td></tr>`).join('') : '<tr><td colspan="7">Sin datos para los filtros.</td></tr>'; window.currentReportRows = rows; }
function renderUsers() { const users = client.listManagedUsers(); $('#usersTable').innerHTML = users.map((user) => `<tr><td>${escapeHtml(user.displayName)}</td><td><select data-user-id="${user.userId}" class="user-role"><option ${user.role === 'Administrador' ? 'selected' : ''}>Administrador</option><option ${user.role === 'Responsable' ? 'selected' : ''}>Responsable</option><option ${user.role === 'Colaborador' ? 'selected' : ''}>Colaborador</option><option ${user.role === 'Observador' ? 'selected' : ''}>Observador</option></select></td><td><button class="user-active table-action" data-user-id="${user.userId}">${user.active ? 'Activo' : 'Inactivo'}</button></td><td>${user.allowedTenantIds.map((tenant) => companyNames[tenant]).join(', ')}</td><td><button class="save-user table-action" data-user-id="${user.userId}">Guardar</button></td></tr>`).join(''); }

function clearProjectSelection() { selectedProjectId = null; activeProjectView = null; render(); }
function showKanban(projectId = null) { if (projectId) { kanbanProjectId = projectId; selectedProjectId = projectId; activeProjectView = 'board'; render(); } $('#kanbanView').classList.remove('hidden'); renderKanban(); $('#kanbanView').scrollIntoView({ behavior: 'smooth', block: 'start' }); setTimeout(() => $('#kanbanProjectHeader').querySelector('h3')?.focus(), 0); }
function openProjectInfo(project) { selectedProjectId = project.id; activeProjectView = 'info'; render(); showDetail(project); }

function showDetail(project) {
  const locked = project.status === 'Cerrado';
  $('#detailProjectId').value = project.id; $('#detailTitle').textContent = 'Configuración del tablero'; $('#detailMeta').textContent = `${project.name} · Responsable: ${project.owner} · Estado: ${project.status}`;
  $('#portfolioSelect').innerHTML = client.listPortfolios().map((portfolio) => `<option value="${portfolio.id}" ${portfolio.id === project.portfolioId ? 'selected' : ''}>${escapeHtml(portfolio.name)}</option>`).join('');
  $('#participantList').innerHTML = project.participants.length ? project.participants.map((participant) => `<li>${escapeHtml(participant.displayName)} · ${escapeHtml(participant.projectRole)}</li>`).join('') : '<li>Sin participantes adicionales.</li>';
  $('#participantSelect').innerHTML = client.listUsers().filter((user) => !project.participants.some((participant) => participant.userId === user.userId)).map((user) => `<option value="${user.userId}">${escapeHtml(user.displayName)}</option>`).join('');
  $('#phaseMilestoneList').innerHTML = `${project.phases.map((phase) => `<div class="detail-task"><span>Fase: ${escapeHtml(phase.name)}</span><strong>${escapeHtml(phase.status)}</strong>${phase.status !== 'Cerrada' ? `<button class="table-action phase-next" data-phase-id="${phase.id}" type="button">Avanzar</button>` : ''}</div>`).join('')}${project.milestones.map((milestone) => `<div class="detail-task"><span>Hito: ${escapeHtml(milestone.name)} · ${escapeHtml(milestone.targetDate)}</span><strong>${escapeHtml(milestone.status)}</strong>${milestone.status !== 'Cumplido' ? `<button class="table-action milestone-complete" data-milestone-id="${milestone.id}" type="button">Cumplir</button>` : ''}</div>`).join('')}` || '<p>Sin fases ni hitos.</p>';
  const nextStatus = project.status === 'Planificación' ? 'En curso' : project.status === 'En curso' ? 'Cerrado' : null;
  $('#statusActions').innerHTML = nextStatus ? `<span>${project.status}</span><button class="secondary-button" id="advanceStatus" type="button">Cambiar a ${nextStatus}</button>` : '<span>Cerrado</span>';
  detailDialog.querySelectorAll('section input, section select, section button').forEach((control) => { control.disabled = locked; });
  detailDialog.showModal();
}

function openCardMenu(project, taskId, anchor) {
  const task = project.tasks.find((item) => item.id === taskId); if (!task) return; const locked = project.status === 'Cerrado'; const done = taskIsDone(project, task); const destinations = project.boardLists.filter((list) => !list.archivedAt && list.id !== task.listId).map((list) => `<button class="card-menu-action" data-action="move" data-list-id="${list.id}">Mover a «${escapeHtml(list.name)}»</button>`).join('');
  cardMenu.innerHTML = `<button class="card-menu-action" data-action="open">Ver detalle de tarjeta</button>${!locked && !done ? destinations : ''}${!locked && !done ? '<button class="card-menu-action" data-action="edit">Editar tarjeta</button>' : ''}${!locked ? '<button class="card-menu-action" data-action="duplicate">Duplicar tarjeta</button><button class="card-menu-action" data-action="archive">Archivar tarjeta</button>' : ''}`;
  cardMenu.querySelectorAll('button').forEach((button) => { button.style.cssText = 'display:block;width:100%;padding:8px;border:0;background:#fff;text-align:left;cursor:pointer'; button.dataset.taskId = taskId; });
  const rect = anchor.getBoundingClientRect(); cardMenu.style.left = `${Math.max(8, rect.right - 190)}px`; cardMenu.style.top = `${rect.bottom + 4}px`; cardMenu.hidden = false;
}

function openListMenu(project, listId, anchor) {
  const list = project.boardLists.find((item) => item.id === listId && !item.archivedAt); if (!list) return;
  const active = project.boardLists.filter((item) => !item.archivedAt).sort((a, b) => a.position - b.position); const index = active.findIndex((item) => item.id === list.id); const isDefault = ['pending', 'progress', 'blocked', 'done'].some((suffix) => list.id === `${project.id}-list-${suffix}`); const isEmpty = !project.tasks.some((task) => task.listId === list.id);
  listMenu.innerHTML = `<button class="list-menu-action" data-action="configure">Configurar lista</button><button class="list-menu-action" data-action="left" ${index === 0 ? 'disabled' : ''}>Mover lista a la izquierda</button><button class="list-menu-action" data-action="right" ${index === active.length - 1 ? 'disabled' : ''}>Mover lista a la derecha</button><button class="list-menu-action" data-action="archive">Archivar lista</button>${!isDefault && isEmpty && active.length > 1 ? '<button class="list-menu-action list-delete-action" data-action="delete">Eliminar lista</button>' : ''}`;
  listMenu.querySelectorAll('button').forEach((button) => { button.style.cssText = 'display:block;width:100%;padding:8px;border:0;background:#fff;text-align:left;cursor:pointer'; button.dataset.listId = listId; });
  const rect = anchor.getBoundingClientRect(); listMenu.style.left = `${Math.max(8, rect.right - 220)}px`; listMenu.style.top = `${rect.bottom + 4}px`; listMenu.hidden = false;
}

