  $('#cardProjectId').value = project.id; $('#cardTaskId').value = task.id; $('#cardTitle').textContent = task.name; $('#cardMeta').textContent = `Proyecto: ${project.name} · Lista: ${list?.name ?? 'Sin lista'}`;
  $('#cardAssignee').innerHTML = users.map((user) => `<option value="${user.displayName}" ${user.displayName === task.assignee ? 'selected' : ''}>${escapeHtml(user.displayName)}</option>`).join('');
