function canDropTask(project, task, destinationId) {
  const source = taskList(project, task); const destination = project.boardLists.find((list) => list.id === destinationId && !list.archivedAt); if (!source || !destination || source.id === destination.id || source.isDone || project.status === 'Cerrado') return false;
  if (destination.wipLimit && project.tasks.filter((item) => !item.archivedAt && item.listId === destination.id).length >= destination.wipLimit) return false;
  if (!destination.isDone) return true;
  const done = (item) => taskIsDone(project, item); const children = project.tasks.filter((item) => item.parentTaskId === task.id && !item.archivedAt); const dependencies = task.dependencies.map((id) => project.tasks.find((item) => item.id === id)).filter(Boolean); return !children.some((item) => !done(item)) && !dependencies.some((item) => !item.archivedAt && !done(item));
}
