function completeLogin(event) {
  event?.preventDefault();
  const button = $('#loginButton');
  const error = $('#loginError');
  const selectedUserId = $('#loginUserSelect').value;
  button.disabled = true;
  error.classList.add('hidden');
  try {
    const result = client.login(selectedUserId);
    if (!result?.ok) throw new Error('No se encontró un usuario activo para iniciar la sesión.');
    $('#loginView').classList.add('hidden');
    document.querySelector('.app-shell').classList.remove('hidden');
    showProjects();
  } catch (loginFailure) {
    $('#loginView').classList.remove('hidden');
    document.querySelector('.app-shell').classList.add('hidden');
    error.textContent = `No se pudo abrir la aplicación: ${loginFailure.message}`;
    error.classList.remove('hidden');
  } finally {
    button.disabled = false;
  }
}
