$('#addCardDependency').addEventListener('click', () => { const predecessorId = $('#cardDependencySelect').value; if (!predecessorId) return; const result = client.addTaskDependency({ projectId: $('#cardProjectId').value, taskId: $('#cardTaskId').value, predecessorId }); if (result.ok) refreshCardDetail(); });
$('#cardStatusActions').addEventListener('click', (event) => { const button = event.target.closest('.card-move'); if (!button) return; const result = client.moveTaskToList({ projectId: $('#cardProjectId').value, taskId: $('#cardTaskId').value, listId: button.dataset.listId }); if (result.ok) refreshCardDetail(); });
$('#addChecklistItem').addEventListener('click', () => { const text = $('#cardChecklistText').value.trim(); if (!text) { showError({ ok: false, error: { code: 'CHECKLIST_ITEM_INVALID', message: 'Escribe un elemento para el checklist.' } }); $('#cardChecklistText').focus(); return; } const result = client.addChecklistItem({ projectId: $('#cardProjectId').value, taskId: $('#cardTaskId').value, text }); if (result.ok) { $('#cardChecklistText').value = ''; refreshCardDetail(); } });
$('#cardChecklist').addEventListener('change', (event) => { const input = event.target.closest('.checklist-toggle'); if (!input) return; const result = client.toggleChecklistItem({ projectId: $('#cardProjectId').value, taskId: $('#cardTaskId').value, checklistItemId: input.dataset.itemId, completed: input.checked }); if (result.ok) refreshCardDetail(); });
$('#cardChecklist').addEventListener('click', (event) => { const button = event.target.closest('.checklist-remove'); if (!button) return; const result = client.removeChecklistItem({ projectId: $('#cardProjectId').value, taskId: $('#cardTaskId').value, checklistItemId: button.dataset.itemId }); if (result.ok) refreshCardDetail(); });
$('#addCardAttachment').addEventListener('click', () => { const name = $('#cardAttachmentName').value.trim(); if (!name) return; const result = client.addAttachment({ projectId: $('#cardProjectId').value, taskId: $('#cardTaskId').value, name, url: $('#cardAttachmentUrl').value.trim() }); if (result.ok) { $('#cardAttachmentName').value = ''; $('#cardAttachmentUrl').value = ''; refreshCardDetail(); } });
$('#addCardComment').addEventListener('click', () => { const text = $('#cardCommentText').value.trim(); if (!text) return; const result = client.addComment({ projectId: $('#cardProjectId').value, taskId: $('#cardTaskId').value, text }); if (result.ok) { $('#cardCommentText').value = ''; refreshCardDetail(); } });
$('#cardMoreMenu').addEventListener('click', (event) => openCardMenu(client.listProjects().find((item) => item.id === $('#cardProjectId').value), $('#cardTaskId').value, event.currentTarget));
function refreshDetail() { const project = client.listProjects().find((item) => item.id === $('#detailProjectId').value); showDetail(project); render(); }
$('#assignPortfolio').addEventListener('click', () => { client.assignPortfolio({ projectId: $('#detailProjectId').value, portfolioId: $('#portfolioSelect').value }); const project = client.listProjects().find((item) => item.id === $('#detailProjectId').value); showDetail(project); render(); });
$('#addParticipant').addEventListener('click', () => { const userId = $('#participantSelect').value; if (!userId) return; client.addParticipant({ projectId: $('#detailProjectId').value, userId, projectRole: $('#participantRole').value }); const project = client.listProjects().find((item) => item.id === $('#detailProjectId').value); showDetail(project); render(); });
$('#addPhase').addEventListener('click', () => { const name = $('#phaseName').value.trim(); if (!name) return; client.createPhase({ projectId: $('#detailProjectId').value, name }); $('#phaseName').value = ''; refreshDetail(); });
$('#addMilestone').addEventListener('click', () => { const name = $('#milestoneName').value.trim(); const targetDate = $('#milestoneDate').value; if (!name || !targetDate) return; client.createMilestone({ projectId: $('#detailProjectId').value, name, targetDate }); $('#milestoneName').value = ''; refreshDetail(); });
$('#phaseMilestoneList').addEventListener('click', (event) => { const projectId = $('#detailProjectId').value; if (event.target.closest('.phase-next')) { const phase = client.listProjects().find((project) => project.id === projectId).phases.find((item) => item.id === event.target.dataset.phaseId); client.changePhaseStatus({ projectId, phaseId: phase.id, status: phase.status === 'Pendiente' ? 'En curso' : 'Cerrada' }); refreshDetail(); } if (event.target.closest('.milestone-complete')) { client.completeMilestone({ projectId, milestoneId: event.target.dataset.milestoneId }); refreshDetail(); } });
detailDialog.addEventListener('click', (event) => { if (event.target.id !== 'advanceStatus') return; const project = client.listProjects().find((item) => item.id === $('#detailProjectId').value); const status = project.status === 'Planificación' ? 'En curso' : 'Cerrado'; client.changeProjectStatus({ projectId: project.id, status }); showDetail(client.listProjects().find((item) => item.id === project.id)); render(); });

render();
